code.after:
interface Mediator {
  notify(sender: string, event: string, payload: unknown): void;
}

class BookingFormMediator implements Mediator {
  constructor(
    private datePicker: DatePicker,
    private seatSelector: SeatSelector,
    private priceDisplay: PriceDisplay
  ) {}

  notify(sender: string, event: string, payload: unknown) {
    if (sender === "datePicker" && event === "dateChanged") {
      this.seatSelector.refreshAvailability(payload as Date);
      this.priceDisplay.updatePrice(payload as Date);
    }
  }
}

class DatePicker {
  constructor(private mediator: Mediator) {}
  onDateChange(date: Date) {
    this.mediator.notify("datePicker", "dateChanged", date); // no direct references
  }
}
